  1	import java.io.PrintStream;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	
  6	final class MST {
  7	    private static final int NO_EDGE = 0;
  8	    private static final int ROOT_PARENT = -1;
  9	    private static final int START_VERTEX = 0;
 10	    private static final int[][] SAMPLE_GRAPH = {
 11	        { 0, 2, 0, 6, 0 },
 12	        { 2, 0, 3, 8, 5 },
 13	        { 0, 3, 0, 0, 7 },
 14	        { 6, 8, 0, 0, 9 },
 15	        { 0, 5, 7, 9, 0 }
 16	    };
 17	
 18	    private MST() {}
 19	
 20	    record Edge(int from, int to, int weight) {}
 21	
 22	    record Result(List<Edge> edges, int totalWeight) {
 23	        Result {
 24	            edges = List.copyOf(edges);
 25	        }
 26	    }
 27	
 28	    @FunctionalInterface
 29	    private interface NeighborVisitor {
 30	        void visit(int vertex, int weight);
 31	    }
 32	
 33	    private static final class Graph {
 34	        private final int[][] adjacencyMatrix;
 35	
 36	        Graph(int[][] adjacencyMatrix) {
 37	            validateAdjacencyMatrix(adjacencyMatrix);
 38	            this.adjacencyMatrix = adjacencyMatrix;
 39	        }
 40	
 41	        int vertexCount() {
 42	            return adjacencyMatrix.length;
 43	        }
 44	
 45	        int edgeWeight(int from, int to) {
 46	            return adjacencyMatrix[from][to];
 47	        }
 48	
 49	        boolean hasEdge(int from, int to) {
 50	            return edgeWeight(from, to) != NO_EDGE;
 51	        }
 52	
 53	        void forEachNeighbor(int from, NeighborVisitor visitor) {
 54	            for (int to = 0; to < vertexCount(); to++) {
 55	                if (hasEdge(from, to)) {
 56	                    visitor.visit(to, edgeWeight(from, to));
 57	                }
 58	            }
 59	        }
 60	    }
 61	
 62	    private static final class PrimState {
 63	        private final int[] parent;
 64	        private final int[] bestEdgeWeight;
 65	        private final boolean[] includedInMst;
 66	
 67	        PrimState(int vertexCount) {
 68	            this.parent = new int[vertexCount];
 69	            this.bestEdgeWeight = new int[vertexCount];
 70	            this.includedInMst = new boolean[vertexCount];
 71	            Arrays.fill(bestEdgeWeight, Integer.MAX_VALUE);
 72	            bestEdgeWeight[START_VERTEX] = 0;
 73	            parent[START_VERTEX] = ROOT_PARENT;
 74	        }
 75	
 76	        int selectNextVertex() {
 77	            int minValue = Integer.MAX_VALUE;
 78	            int minIndex = -1;
 79	
 80	            for (int vertex = 0; vertex < includedInMst.length; vertex++) {
 81	                if (!includedInMst[vertex] && bestEdgeWeight[vertex] < minValue) {
 82	                    minValue = bestEdgeWeight[vertex];
 83	                    minIndex = vertex;
 84	                }
 85	            }
 86	
 87	            return minIndex;
 88	        }
 89	
 90	        void include(int vertex) {
 91	            includedInMst[vertex] = true;
 92	        }
 93	
 94	        boolean isIncluded(int vertex) {
 95	            return includedInMst[vertex];
 96	        }
 97	
 98	        void updateConnection(int vertex, int newParent, int edgeWeight) {
 99	            if (!isIncluded(vertex) && edgeWeight < bestEdgeWeight[vertex]) {
100	                parent[vertex] = newParent;
101	                bestEdgeWeight[vertex] = edgeWeight;
102	            }
103	        }
104	
105	        Result toResult(Graph graph) {
106	            List<Edge> edges = new ArrayList<>();
107	            int totalWeight = 0;
108	
109	            for (int vertex = 1; vertex < graph.vertexCount(); vertex++) {
110	                int from = parent[vertex];
111	                int weight = graph.edgeWeight(from, vertex);
112	
113	                edges.add(new Edge(from, vertex, weight));
114	                totalWeight += weight;
115	            }
116	
117	            return new Result(edges, totalWeight);
118	        }
119	    }
120	
121	    private static void validateAdjacencyMatrix(int[][] graph) {
122	        if (graph == null) {
123	            throw new IllegalArgumentException("Graph must not be null.");
124	        }
125	
126	        if (graph.length == 0) {
127	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
128	        }
129	
130	        for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
131	            int[] row = graph[rowIndex];
132	            if (row == null) {
133	                throw new IllegalArgumentException("Graph rows must not be null.");
134	            }
135	
136	            if (row.length != graph.length) {
137	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
138	            }
139	
140	            for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
141	                if (row[columnIndex] != graph[columnIndex][rowIndex]) {
142	                    throw new IllegalArgumentException(
143	                        "Graph must represent an undirected adjacency matrix."
144	                    );
145	                }
146	            }
147	        }
148	    }
149	
150	    private static void relaxOutgoingEdges(Graph graph, PrimState state, int currentVertex) {
151	        state.include(currentVertex);
152	        graph.forEachNeighbor(currentVertex,
153	            (neighbor, edgeWeight) -> state.updateConnection(neighbor, currentVertex, edgeWeight));
154	    }
155	
156	    static Result computeMinimumSpanningTree(int[][] graph) {
157	        return computeMinimumSpanningTree(new Graph(graph));
158	    }
159	
160	    private static Result computeMinimumSpanningTree(Graph graph) {
161	        int vertexCount = graph.vertexCount();
162	        PrimState state = new PrimState(vertexCount);
163	
164	        for (int count = 0; count < vertexCount - 1; count++) {
165	            int currentVertex = state.selectNextVertex();
166	
167	            if (currentVertex == -1) {
168	                throw new IllegalStateException("Graph must be connected.");
169	            }
170	
171	            relaxOutgoingEdges(graph, state, currentVertex);
172	        }
173	
174	        return state.toResult(graph);
175	    }
176	
177	    static String renderResult(Result result) {
178	        StringBuilder output = new StringBuilder("Edge \tWeight\n");
179	        for (Edge edge : result.edges()) {
180	            output.append(edge.from())
181	                .append(" - ")
182	                .append(edge.to())
183	                .append('\t')
184	                .append(edge.weight())
185	                .append('\n');
186	        }
187	        return output.toString();
188	    }
189	
190	    static void printResult(PrintStream out, Result result) {
191	        out.print(renderResult(result));
192	    }
193	
194	    public static void main(String[] args)
195	    {
196	        Result result = computeMinimumSpanningTree(SAMPLE_GRAPH);
197	        printResult(System.out, result);
198	    }
199	}
